  "settings.modelProvider.help.contextWindow": "La capacidad de contexto que el modelo puede procesar a la vez, en tokens. ZAICODE la usa para gestionar el contexto.\nNo superes el límite real del modelo.",
  "settings.modelProvider.help.maxOutputTokens": "El número máximo de tokens que una sola solicitud al modelo puede generar.\nNo superes el límite real del modelo.",
  "settings.modelProvider.help.inputModalities": "Define los tipos de contenido que el modelo puede recibir:\n\n- **Texto**: Recibe contenido de texto. Obligatorio.\n- **Imágenes**: Recibe contenido de imagen.\n- **Vídeo**: Recibe contenido de vídeo.\n- **PDF**: Recibe documentos PDF directamente.",
  "settings.modelProvider.help.outputModalities": "El tipo de contenido de las respuestas del modelo. Actualmente solo se admite texto.",
  "settings.modelProvider.help.capabilities": "- **Salida estructurada**: Admite restricciones de JSON Schema sobre los campos, los tipos y la estructura de la salida.\n- **Búsqueda web nativa**: Admite la búsqueda web integrada en la API del modelo.\n- **Mensajes del sistema a mitad de conversación**: Admite insertar instrucciones del sistema durante una conversación.\n\nNo actives capacidades que el modelo no admita.",
  "settings.modelProvider.help.reasoningLevelsOrdered": "Define los niveles de razonamiento disponibles en el chat. **Deben ordenarse de menor a mayor esfuerzo de razonamiento**.\nNo configures niveles de razonamiento que el modelo no admita.",
  "settings.modelProvider.help.reasoningLevelMapping": "Usa una expresión CEL para asignar el nivel de razonamiento actual, `reasoningLevel`, a los campos de la solicitud a la API del modelo. El objeto JSON devuelto por la expresión se fusiona con el cuerpo de la solicitud saliente.",
  "settings.modelProvider.help.advanced": "**Esquema de herramientas MFJS**: Activa la compatibilidad con Moonshot Flavored JSON Schema, usada habitualmente por la API del modelo Kimi de Moonshot. Actívalo solo cuando la API del modelo requiera este formato.",
  "settings.modelProvider.help.followRecommendedConfig": "Coincide con la configuración recomendada según el ID de modelo, la URL base y el formato de API. ZAICODE actualiza continuamente las recomendaciones y te las sincroniza automáticamente.\nCuando cambies un ajuste manualmente, ese ajuste pasa a gestionarse manualmente y deja de seguir las actualizaciones de la recomendación; el resto sigue gestionado por la configuración inteligente.",
